package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import com.lqq.supportflow.shared.ConflictException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RegisterKnowledgeDocumentService { private final KnowledgeDocumentPort documents; private final KnowledgeBasePort knowledgeBases; private final KnowledgeChunkPort chunks; private final TextChunker chunker=new TextChunker(); public RegisterKnowledgeDocumentService(KnowledgeDocumentPort documents,KnowledgeBasePort knowledgeBases,KnowledgeChunkPort chunks){this.documents=documents;this.knowledgeBases=knowledgeBases;this.chunks=chunks;} @Transactional public KnowledgeDocument register(Long t,Long b,String f,String content){return registerExtracted(t,b,f,ContentHasher.sha256(content),content);} @Transactional public KnowledgeDocument registerExtracted(Long t,Long b,String f,String hash,String content){if(!knowledgeBases.belongsTo(t,b))throw new IllegalArgumentException("knowledge base does not belong to tenant");if(documents.exists(t,b,hash))throw new ConflictException("duplicate document content");KnowledgeDocument document=documents.save(t,b,f,hash);document=documents.transitionStatus(t,document.id(),document.status(),IngestionStatus.PARSING);document=documents.transitionStatus(t,document.id(),document.status(),IngestionStatus.CHUNKING);chunks.saveAll(t,b,document.id(),chunker.chunk(content));return documents.transitionStatus(t,document.id(),document.status(),IngestionStatus.EMBEDDING);}}
